# wan-vace — generated by tools/gen_model_py.py from the yaml
# cascade (2026-09-02 flip), then hand-edited since. The
# class IS the unit: family head → variants → quant cells;
# merged_defaults() walks the cascade. Parity pinned by
# tests/walls/suites/test_python_models.py + the http goldens.
#
# SSOT law: this file REPLACES model.yaml + variants/. A
# model.yaml reappearing next to it is a LOUD refusal.


from melite_models import  KnobRow,Model, LaneInputs, Variant, Cell, LoraRow, Genre, ClipType








class WanVace(Model):
    id = 'wan-vace'
    genre = Genre.VIDEO
    label = 'Wan2.2 VACE'
    description = 'Wan2.2 VACE video generation with reference-frame and mask control.'
    engine = 'comfyui'
    card = 'video-gen'
    # loader facts the renderer reads; the family's extra
    # weights (VACE module / Lightning LoRA) ride defaults
    # + the renderer doc — the template is the SSOT graph
    lane_inputs = LaneInputs(
        # the MERGED vace checkpoint (base ∪ Fun module delta,
        # file-level union — the module standalone refuses to load)
        unet='Wan2_2_VACE_A14B_HIGH_fp8_e4m3fn_scaled_KJ_merged.safetensors',
        text_encoder='umt5_xxl_fp8_e4m3fn_converted.safetensors',
        clip_type=ClipType.WAN,
        vae='Wan2_1_VAE_bf16.safetensors',
    )
    form = 'form_video_director'
    defaults = dict(
            width=832,
            height=480,
            length=49,
            fps=24,
            steps=4,            # Lightning 4-step LoRA rides by default
            cfg=1.0,
            sampler='euler',
            scheduler='simple',
            seed=42,
        )
    # the cascade as frozen rows (PYTHON SHAPE LAW rung 1)
    variants = (
        Variant(id='base', label='Base', hint='DEFAULT — 25-step HIGH fp8 checkpoint, director-quality', route='wan-vace', order=0),
        Variant(id='custom_fast', label='Custom Fast', hint='6-step + lightx2v distill LoRA on the base HIGH model', route='wan-vace', order=2),
        Variant(id='custom_quality', label='Custom Quality', hint='30-step HIGH expert — maximum detail', route='wan-vace', order=1),
        Variant(id='lightning', label='Lightning', hint='4-step + Wan Lightning LoRA on the base HIGH model (~6× faster)', route='wan-vace', order=3),
    )

    # the video-gen card surface for the wan-vace arm (row 3,
    # 2026-09-06 — eleventh card in the KnobRow migration, second
    # multi-arm one). Twelve rows: the shared prompt/sampler block
    # plus the anchor frame. model/lora/t5/vae names ride the step
    # doc as lane facts, never the wire — no rows.
    card_knobs = (
        KnobRow(card='prompt', inject='CLIPTextEncode.0.text', kind='s'),
        KnobRow(card='negative_prompt', inject='CLIPTextEncode.1.text', kind='s'),
        KnobRow(card='reference_image', inject='LoadImage.0.image', kind='s'),
        KnobRow(card='width', inject='WanVaceToVideo.0.width', kind='n'),
        KnobRow(card='height', inject='WanVaceToVideo.0.height', kind='n'),
        KnobRow(card='length', inject='WanVaceToVideo.0.length', kind='n'),
        KnobRow(card='fps', inject='VHS_VideoCombine.0.frame_rate', kind='n'),
        KnobRow(card='seed', inject='KSampler.0.seed', kind='n'),
        KnobRow(card='steps', inject='KSampler.0.steps', kind='n'),
        KnobRow(card='cfg', inject='KSampler.0.cfg', kind='n'),
        KnobRow(card='sampler', inject='KSampler.0.sampler_name', kind='s'),
        KnobRow(card='scheduler', inject='KSampler.0.scheduler', kind='s'),
    )

